export const PET_INDIVIDUAL_ODDS={
 // Relative weights are normalized against the remaining obtainable pets at draw time.
 common:[15,15,15,14,12,11,9,5],
 rare:[15,15,14,12,10,9,7,5],
 legendary:[15,14,13,12,10,9,7,5],
 mythic:[15,14,13,12,10,9,7,5],
 secret:[25,22,18,15,12,8]
};
export function getPetFusionPool(rarity){return PETS.filter(p=>p.rarity===rarity&&!p.adminOnly&&!p.uniqueReward&&!p.unobtainable)}
export function getPetFusionWeights(rarity){const pool=getPetFusionPool(rarity),weights=PET_INDIVIDUAL_ODDS[rarity]||[];return pool.map((pet,index)=>{const weight=Number(weights[index]);return Number.isFinite(weight)&&weight>=0?weight:1})}
export function randomPet(rarity){const arr=getPetFusionPool(rarity);if(!arr.length)return PETS.find(p=>!p.unobtainable)||PETS[0];const weights=getPetFusionWeights(rarity),total=weights.reduce((sum,weight)=>sum+weight,0);if(total<=0)return arr[Math.floor(Math.random()*arr.length)];let roll=Math.random()*total;for(let i=0;i<arr.length;i++){roll-=weights[i];if(roll<0)return arr[i]}return arr[arr.length-1]}
